          "customFunctionJavascriptFunction": "const iterationResults = $retrieverOutput;\nconst seen = {};\nconst blocks = [];\n\nconst resultsArray = Array.isArray(iterationResults) ? iterationResults : [iterationResults];\n\nfor (let i = 0; i < resultsArray.length; i++) {\n  const result = resultsArray[i];\n  let parsed;\n  try {\n    parsed = typeof result === \"string\" ? JSON.parse(result) : result;\n  } catch (e) {\n    continue;\n  }\n\n  let docs;\n  if (Array.isArray(parsed)) {\n    docs = parsed;\n  } else if (parsed && parsed.sourceDocuments) {\n    docs = parsed.sourceDocuments;\n  } else {\n    docs = [parsed];\n  }\n\n  for (let j = 0; j < docs.length; j++) {\n    const doc = docs[j];\n    const content = (doc && (doc.pageContent || doc.text)) || \"\";\n    const meta = doc?.metadata || {};\n    const page = meta[\"loc.pageNumber\"] ?? \"?\";\n    const key = content.slice(0, 80);\n\n    if (content && !seen[key]) {\n      seen[key] = true;\n      blocks.push(\"[Page: \" + page + \"]\\n\" + content);\n    }\n  }\n}\n\nreturn { aggregatedContext: blocks.join(\"\\n\\n---\\n\\n\") };",
